begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table history_fixture(name text primary key,id uuid,stamp timestamptz);
grant all on history_fixture to authenticated;
do $$declare t uuid; b uuid; d uuid; a uuid; u uuid; r text; flow uuid; begin
 insert into tenants(name,slug) values('Synthetic forms history','synthetic-forms-history') returning id into t;
 insert into branches(tenant_id,name,code) values(t,'Synthetic branch','HIS') returning id into b;
 insert into departments(tenant_id,branch_id,name,code) values(t,b,'Synthetic department','HIS') returning id into d;
 insert into history_fixture(name,id) values('tenant',t);
 foreach r in array array['admin','staff','inactive'] loop
  insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at)
  values(gen_random_uuid(),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',r||'-forms-history@test.local','x',now(),now()) returning id into a;
  insert into user_profiles(tenant_id,auth_user_id,branch_id,department_id,employee_name,employee_code,email,user_role,working_status,is_login_enabled)
  values(t,a,b,d,r,r||'-HIS',r||'-forms-history@test.local',case when r='staff' then 'staff'::user_role else 'admin'::user_role end,case when r='inactive' then 'inactive'::working_status else 'active'::working_status end,true) returning id into u;
  insert into history_fixture(name,id) values(r,u),(r||'_auth',a);
 end loop;
 insert into fms_flows(tenant_id,family_id,version,name,scope_type,status,is_active,created_by,updated_by)
 values(t,gen_random_uuid(),1,'Synthetic source workflow','tenant','draft',true,(select id from history_fixture where name='admin'),(select id from history_fixture where name='admin')) returning id into flow;
 insert into fms_stages(fms_flow_id,stage_key,name,step_type,sort_order,is_required,planned_time_rule)
 values(flow,'start','Synthetic source stage','form',0,true,'{"deadlineEnabled":false}');
 insert into history_fixture(name,id) values('flow',flow);
 insert into tenants(name,slug) values('Synthetic other history tenant','synthetic-other-history') returning id into t;
 insert into form_templates(tenant_id,name) values(t,'Synthetic other form') returning id into u;
 insert into history_fixture(name,id) values('cross_form',u);
end$$;
update user_profiles set account_status='inactive' where id=(select id from history_fixture where name='inactive');
select ok(not has_table_privilege('authenticated','form_family_provenance','SELECT'),'raw workflow provenance is private');
select ok(not has_table_privilege('authenticated','form_definition_checkpoints','INSERT'),'history cannot be inserted directly');
select ok(not has_table_privilege('authenticated','form_definition_checkpoints','UPDATE'),'history cannot be overwritten directly');
select ok(not has_function_privilege('anon','save_form_workspace_with_audit(uuid,jsonb,jsonb,timestamptz,jsonb,text)','EXECUTE'),'anonymous saves are denied');
select ok(not has_function_privilege('service_role','restore_form_checkpoint_with_audit(uuid,boolean,uuid)','EXECUTE'),'service role is not a form author');
select ok(not has_function_privilege('authenticated','save_form_draft_before_checkpoints(uuid,jsonb,jsonb)','EXECUTE'),'old writer cannot bypass checkpoint wrapper');
select record_form_checkpoint((select id from history_fixture where name='cross_form'),'created');
insert into history_fixture(name,id) select 'cross_checkpoint',id from form_definition_checkpoints where template_id=(select id from history_fixture where name='cross_form');
select set_config('request.jwt.claim.sub',(select id::text from history_fixture where name='admin_auth'),true);
select set_config('request.jwt.claim.role','authenticated',true);
set local role authenticated;
insert into history_fixture(name,id) select 'form',save_form_workspace_with_audit(null,'{"name":"Synthetic history form","permissions":{"roles":["staff"]},"record_name_field_key":"client_name"}','[{"key":"client_name","label":"Client Name","type":"text"}]',null,'{"kind":"ai_import"}','Initial draft');
select is(jsonb_array_length(list_form_history((select id from history_fixture where name='form'))),1,'creation has one complete checkpoint');
select is(list_form_history((select id from history_fixture where name='form'))->0->>'change_note','Initial draft','change note is saved transactionally');
select is(list_form_history((select id from history_fixture where name='form'))->0#>>'{definition,recordNameFieldKey}','client_name','record-name wrapper completed before checkpoint');
select is(get_form_provenance(array[(select id from history_fixture where name='form')])#>>array[(select id::text from history_fixture where name='form'),'origin'],'ai_import','import creation has immutable origin');
update history_fixture set stamp=(select updated_at from form_templates where id=history_fixture.id) where name='form';
select lives_ok($$select save_form_workspace_with_audit((select id from history_fixture where name='form'),'{"name":"Synthetic history form","permissions":{"roles":["staff"]},"record_name_field_key":"client_name"}','[{"key":"client_name","label":"Client Name","type":"text"}]',(select stamp from history_fixture where name='form'))$$,'unchanged workspace save succeeds');
select is(jsonb_array_length(list_form_history((select id from history_fixture where name='form'))),1,'unchanged definition creates no checkpoint');
select throws_ok($$select save_form_workspace_with_audit((select id from history_fixture where name='form'),'{"name":"Stale overwrite"}','[]','2000-01-01'::timestamptz)$$,'40001',null,'stale timestamp cannot overwrite a definition');
select throws_ok($$select save_form_workspace_with_audit((select id from history_fixture where name='form'),'{"name":"Overwrite"}','[]',null)$$,'40001',null,'existing saves require a concurrency timestamp');
reset role;
update form_fields set initial_value='Synthetic legacy default' where form_template_id=(select id from history_fixture where name='form');
set local role authenticated;
select lives_ok($$select publish_form_with_audit((select id from history_fixture where name='form'))$$,'existing publish wrapper succeeds');
select is(list_form_history((select id from history_fixture where name='form'))->0->>'lifecycle','published','publish is checkpointed');
insert into history_fixture(name,id) select 'submission',submit_form_with_audit((select id from history_fixture where name='form'),'{"client_name":"Synthetic client answer"}',null,null);
insert into history_fixture(name,id) select 'published_checkpoint',(list_form_history((select id from history_fixture where name='form'))->0->>'id')::uuid;
select lives_ok($$select save_published_form_with_audit((select id from history_fixture where name='form'),'{"name":"Synthetic edited published","permissions":{"roles":["staff"]},"record_name_field_key":"client_name"}','[{"key":"client_name","label":"Changed Client Name","type":"text"}]')$$,'old published save RPC is checkpointed');
select is(list_form_history((select id from history_fixture where name='form'))->0->>'action','published_edit','published in-place edit records its action');
select is(list_form_history((select id from history_fixture where name='form'))->0#>>'{definition,fields,0,label}','Changed Client Name','published checkpoint captures final fields');
insert into history_fixture(name,id) select 'latest',(list_form_history((select id from history_fixture where name='form'))->0->>'id')::uuid;
select throws_ok($$select restore_form_checkpoint_with_audit((select id from history_fixture where name='published_checkpoint'),false,(select id from history_fixture where name='published_checkpoint'))$$,'40001',null,'restore refuses stale family history');
insert into history_fixture(name,id) select 'restored',restore_form_checkpoint_with_audit((select id from history_fixture where name='published_checkpoint'),false,(select id from history_fixture where name='latest'));
select is((select lifecycle from form_templates where id=(select id from history_fixture where name='restored')),'draft','restore creates a draft');
select is((select family_id from form_templates where id=(select id from history_fixture where name='restored')),(select family_id from form_templates where id=(select id from history_fixture where name='form')),'restore preserves family');
select is((select version from form_templates where id=(select id from history_fixture where name='restored')),2,'restore allocates next numbered version');
select is(list_form_history((select id from history_fixture where name='form'))->0#>>'{definition,fields,0,label}','Client Name','restore uses the exact selected checkpoint');
select is((select initial_value from form_fields where form_template_id=(select id from history_fixture where name='restored')),'Synthetic legacy default','restore preserves legacy defaults without widening native write inputs');
select is((select name from form_templates where id=(select id from history_fixture where name='form')),'Synthetic edited published','restore leaves original published template untouched');
select is((select data->>'client_name' from form_submissions where id=(select id from history_fixture where name='submission')),'Synthetic client answer','restore leaves historical submitted answers untouched');
select is((select template_snapshot#>>'{template,name}' from form_submissions where id=(select id from history_fixture where name='submission')),'Synthetic history form','published edits and restore leave submission snapshots untouched');
update history_fixture set id=(list_form_history((select id from history_fixture where name='form'))->0->>'id')::uuid where name='latest';
select throws_ok($$select restore_form_checkpoint_with_audit((select id from history_fixture where name='published_checkpoint'),false,(select id from history_fixture where name='latest'))$$,'23505',null,'restore never discards an existing draft');
insert into history_fixture(name,id) select 'copy',restore_form_checkpoint_with_audit((select id from history_fixture where name='published_checkpoint'),true,(select id from history_fixture where name='latest'));
select isnt((select family_id from form_templates where id=(select id from history_fixture where name='copy')),(select family_id from form_templates where id=(select id from history_fixture where name='form')),'copy creates a new family');
select is(get_form_provenance(array[(select id from history_fixture where name='copy')])#>>array[(select id::text from history_fixture where name='copy'),'origin'],'duplicate','checkpoint copy records duplicate attribution');
insert into history_fixture(name,id) select 'duplicate',duplicate_form_with_audit((select id from history_fixture where name='form'),'Synthetic duplicate');
select is(jsonb_array_length(list_form_history((select id from history_fixture where name='duplicate'))),1,'legacy duplicate RPC creates history');
select lives_ok($$select archive_form_with_audit((select id from history_fixture where name='copy'))$$,'direct archive keeps the existing audited behavior');
select is(list_form_history((select id from history_fixture where name='copy'))->0->>'lifecycle','archived','direct archive records the lifecycle transition');
select lives_ok($$select publish_form_with_audit((select id from history_fixture where name='restored'))$$,'revision publication preserves the existing publisher');
select ok(exists(select 1 from jsonb_array_elements(list_form_history((select id from history_fixture where name='form'))) event where event->>'template_id'=(select id::text from history_fixture where name='form') and event->>'action'='archived'),'publishing a new version records archival of the preceding version');
select throws_ok($$select save_form_workspace_with_audit((select id from history_fixture where name='cross_form'),'{"name":"Cross tenant overwrite"}','[]',now())$$,'42501',null,'cross-tenant definition writes are denied before mutation');
insert into history_fixture(name,id) select 'fms_form',save_form_workspace_with_audit(null,'{"name":"Synthetic FMS-created form","permissions":{"roles":["staff"]}}','[{"key":"note","label":"Note","type":"text"}]',null,jsonb_build_object('kind','fms','flow_id',(select id from history_fixture where name='flow'),'stage_key','start'));
select is(get_form_provenance(array[(select id from history_fixture where name='fms_form')])#>>array[(select id::text from history_fixture where name='fms_form'),'source_stage_name'],'Synthetic source stage','source names come from verified persisted workflow');
select throws_ok($$select save_form_workspace_with_audit(null,'{"name":"Forged stage"}','[]',null,jsonb_build_object('kind','fms','flow_id',(select id from history_fixture where name='flow'),'stage_key','made-up'))$$,'23514',null,'forged source stage is rejected');
select publish_form_with_audit((select id from history_fixture where name='fms_form'));
select throws_ok($$select list_form_history((select id from history_fixture where name='cross_form'))$$,'42501',null,'other tenant history is denied');
select is(get_form_provenance(array[(select id from history_fixture where name='cross_form')]),'{}'::jsonb,'other tenant provenance is omitted');
select throws_ok($$select restore_form_checkpoint_with_audit((select id from history_fixture where name='cross_checkpoint'),true,(select id from history_fixture where name='cross_checkpoint'))$$,'42501',null,'other tenant checkpoint restoration is denied');
insert into history_fixture(name,id) select 'rich',save_form_workspace_with_audit(null,
'{"name":"Synthetic rich definition","description":"Roundtrip fixture","permissions":{"roles":["staff","admin"]},"record_name_field_key":"purchase","sections":[{"key":"start","title":"Visit","next":"follow"},{"key":"follow","title":"Follow-up","next":"__submit__"}]}',
'[{"key":"purchase","label":"Purchased?","type":"radio","required":true,"sectionKey":"start","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"branches":[{"operator":"equals","value":"yes","targetSectionKey":"__submit__"}]},{"key":"reason","label":"Reason","type":"select","sectionKey":"start","options":[{"value":"price","label":"Price"},{"value":"design","label":"Design"}],"condition":{"fieldKey":"purchase","operator":"equals","value":"no"}},{"key":"budget","label":"Budget","type":"currency","sectionKey":"start","validation":{"min":0,"max":100000},"helperText":"Estimate","placeholder":"Amount","rule":{"kind":"all","rules":[{"kind":"predicate","fieldKey":"purchase","operator":"equals","value":"no"},{"kind":"any","rules":[{"kind":"predicate","fieldKey":"reason","operator":"equals","value":"price"},{"kind":"predicate","fieldKey":"reason","operator":"equals","value":"design"}]}]}},{"key":"follow_date","label":"Follow-up date","type":"date","sectionKey":"follow"}]',null);
insert into history_fixture(name,id) select 'rich_copy',restore_form_checkpoint_with_audit((list_form_history((select id from history_fixture where name='rich'))->0->>'id')::uuid,true,(list_form_history((select id from history_fixture where name='rich'))->0->>'id')::uuid);
select is(list_form_history((select id from history_fixture where name='rich_copy'))->0->'definition',list_form_history((select id from history_fixture where name='rich'))->0->'definition','rich definition restores nested rules, routes, sections, options, validation, permissions and naming exactly');
insert into history_fixture(name,id) select 'request',start_forms_import_request('03460000-0000-0000-0000-000000000001');
select throws_ok($$select start_forms_import_request('03460000-0000-0000-0000-000000000001')$$,'P0001','forms_import_duplicate_request','one request key cannot start two model calls');
select lives_ok($$select finish_forms_import_request((select id from history_fixture where name='request'),false)$$,'failed import completion is recorded');
select throws_ok($$select finish_forms_import_request((select id from history_fixture where name='request'),true)$$,'42501',null,'a finished request cannot be changed');
select start_forms_import_request(gen_random_uuid()) from generate_series(1,9);
select throws_ok($$select start_forms_import_request(gen_random_uuid())$$,'P0001','forms_import_daily_limit_reached','ten attempted imports consume the daily quota atomically');
reset role;
select throws_ok($$update form_definition_checkpoints set action='tampered' where template_id=(select id from history_fixture where name='form')$$,'55000',null,'even privileged updates cannot rewrite history');
select throws_ok($$delete from form_family_provenance where family_id=(select family_id from form_templates where id=(select id from history_fixture where name='form'))$$,'55000',null,'provenance cannot be deleted');
select set_config('request.jwt.claim.sub',(select id::text from history_fixture where name='staff_auth'),true);
set local role authenticated;
select throws_ok($$select list_form_history((select id from history_fixture where name='form'))$$,'42501',null,'ordinary staff cannot read author-only definition history');
select throws_ok($$select start_forms_import_request(gen_random_uuid())$$,'42501',null,'ordinary staff cannot use AI quota RPC');
select is(get_form_provenance(array[(select id from history_fixture where name='fms_form')])#>>array[(select id::text from history_fixture where name='fms_form'),'origin'],'fms','ordinary viewers can see origin for an accessible library form');
select ok(not (get_form_provenance(array[(select id from history_fixture where name='fms_form')])->(select id::text from history_fixture where name='fms_form') ? 'source_flow_name'),'ordinary viewers cannot read restricted workflow labels');
select ok(not (get_form_provenance(array[(select id from history_fixture where name='fms_form')])->(select id::text from history_fixture where name='fms_form') ? 'source_flow_id'),'ordinary viewers cannot read restricted workflow IDs');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from history_fixture where name='inactive_auth'),true);
set local role authenticated;
select throws_ok($$select start_forms_import_request(gen_random_uuid())$$,'42501',null,'inactive authors cannot import');
select throws_ok($$select get_form_provenance(array[(select id from history_fixture where name='form')])$$,'42501',null,'inactive authors cannot inspect provenance');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from history_fixture where name='admin_auth'),true);
update fms_stages set form_template_id=(select id from history_fixture where name='fms_form') where fms_flow_id=(select id from history_fixture where name='flow');
set local role authenticated;
select lives_ok($$select restore_form_checkpoint_with_audit((list_form_history((select id from history_fixture where name='fms_form'))->0->>'id')::uuid,true,(list_form_history((select id from history_fixture where name='fms_form'))->0->>'id')::uuid)$$,'copying an FMS-created checkpoint creates a separate draft');
select is((select form_template_id from fms_stages where fms_flow_id=(select id from history_fixture where name='flow')),(select id from history_fixture where name='fms_form'),'checkpoint copy preserves the exact workflow template reference');
reset role;
insert into tenant_section_controls(tenant_id,section_availability) values((select id from history_fixture where name='tenant'),'{"fms_builder":false}') on conflict(tenant_id) do update set section_availability=tenant_section_controls.section_availability||'{"fms_builder":false}';
set local role authenticated;
select is(get_form_provenance(array[(select id from history_fixture where name='fms_form')])#>>array[(select id::text from history_fixture where name='fms_form'),'used_in_fms'],'false','disabled FMS section hides even linkage metadata');
select ok(not (get_form_provenance(array[(select id from history_fixture where name='fms_form')])->(select id::text from history_fixture where name='fms_form') ? 'source_flow_id'),'disabled FMS section hides source links');
reset role;
update tenant_section_controls set section_availability=section_availability||'{"forms_library":false}' where tenant_id=(select id from history_fixture where name='tenant');
set local role authenticated;
select throws_ok($$select start_forms_import_request(gen_random_uuid())$$,'42501',null,'disabled Forms module prevents AI imports');
select throws_ok($$select list_form_history((select id from history_fixture where name='form'))$$,'42501',null,'disabled Forms module prevents history reads');
reset role;
select * from finish();
rollback;
